'use client';
import { useState } from 'react';
import AppShell from '../../app/components/app-shell';
import TimeClock from '../../app/time-clock/time-clock';
import type { Company, Member } from '../../lib/agent-types';
import type { TimeClockData, TimeClockEntry, TimeClockEntriesData } from '../../lib/time-clock-types';
const companies:Company[]=[{id:'11111111-1111-4111-8111-111111111111',name:'Northstar Demo',time_zone:'Europe/London'},{id:'22222222-2222-4222-8222-222222222222',name:'Westfield Demo',time_zone:'America/New_York'}];
const actorId='44444444-4444-4444-8444-444444444444';
function seed(company:Company,role:Member['role']):TimeClockData {return {company,role,actorId,agent:{id:'33333333-3333-4333-8333-333333333333',name:company.id===companies[0].id?'Alex Demo':'Casey Sample'},jobs:[{id:'55555555-5555-4555-8555-555555555555',name:'Reception',status:'active',revision:1},{id:'66666666-6666-4666-8666-666666666666',name:'Site visits',status:'active',revision:1}],entry:null,serverTime:'2026-10-04T08:00:00Z',canManageJobs:role==='owner'||role==='admin',canViewAttendance:role==='owner'||role==='admin'};}
function sheets(data:TimeClockData):TimeClockEntriesData {const entry:TimeClockEntry={id:'77777777-7777-4777-8777-777777777777',tenant_id:data.company.id,agent_id:data.agent!.id,agent_name:data.agent!.name,job_id:data.jobs[0].id,job_name:'Reception',started_at:'2026-10-03T08:00:00Z',ended_at:'2026-10-03T16:00:00Z',revision:4,breaks:[{id:'88888888-8888-4888-8888-888888888888',paid:false,started_at:'2026-10-03T12:00:00Z',ended_at:'2026-10-03T12:30:00Z'}],elapsed_seconds:28800,unpaid_break_seconds:1800,paid_seconds:27000};return {entries:[entry],nextCursor:'synthetic-older',serverTime:data.serverTime,timeZone:data.company.time_zone};}
export default function Review(){const [company,setCompany]=useState(companies[0]);const [role,setRole]=useState<Member['role']>('owner');const initialData=seed(company,role);return <AppShell companyName={company.name} companyId={company.id} activeModule="users" accountName="Synthetic reviewer"><div aria-label="Synthetic Time Clock controls" style={{padding:'12px 20px',display:'flex',gap:12,flexWrap:'wrap'}}><button onClick={()=>setCompany(company.id===companies[0].id?companies[1]:companies[0])}>Switch demo company</button><button onClick={()=>setRole(role==='owner'?'employee':'owner')}>Switch demo role</button></div><TimeClock company={company} role={role} initialData={initialData} initialTimesheets={sheets(initialData)}/></AppShell>;}
